import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { imageAlt, imageSpans, splitImageAlt } from '../src/imagesize';

// Same vectors as mlcext (testdata/imagesize.json, generated by TestImageSizeVectors).
const vectors = JSON.parse(
  readFileSync(resolve(process.cwd(), '../../mlcext/testdata/imagesize.json'), 'utf8'),
) as { alt: string; text: string; size: Record<string, number>; error?: boolean }[];

describe('image size = mlcext', () => {
  for (const v of vectors) {
    it(JSON.stringify(v.alt), () => {
      expect(splitImageAlt(v.alt)).toEqual({ text: v.text, size: v.size, error: v.error ?? false });
      if (!v.error && Object.keys(v.size).length > 0) {
        expect(splitImageAlt(imageAlt(v.text, v.size))).toEqual({ text: v.text, size: v.size, error: false });
      }
    });
  }
});

describe('imageSpans', () => {
  it('finds alt and target of inline images', () => {
    const text = 'a ![Foto|200](bild.png "Titel") b ![](<mit leer.png>)';
    const spans = imageSpans(text);
    expect(spans).toHaveLength(2);
    expect(spans[0]).toMatchObject({ alt: 'Foto|200', target: 'bild.png' });
    expect(text.slice(spans[0].from, spans[0].to)).toBe('![Foto|200](bild.png "Titel")');
    expect(text.slice(spans[0].altFrom, spans[0].altTo)).toBe('Foto|200');
    expect(spans[1]).toMatchObject({ alt: '', target: 'mit leer.png' });
    expect(spans[1].altFrom).toBe(spans[1].altTo);
  });
  it('ignores links and reference images', () => {
    expect(imageSpans('[a](b.png) ![a][ref]')).toEqual([]);
  });
});
